Translate the following GNU C++17 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to translate:
<original_code>
#include <cstdio>
#include <cmath>
#include <iostream>
#include <algorithm>
using namespace std;
long long num11[20];
long long pow10[20];
int ans = 0;
void pre()
{
    pow10[0] = 1;
    for (int i = 1; i <= 17; i++)
    {
        pow10[i] = pow10[i - 1] * 10;
    }
    for (int i = 1; i <= 17; i++)
    {
        num11[i] = num11[i - 1] * 10 + 1;
        // cout << i << ' ' << num11[i] << '\n';
    }
}
int get_len(long long x)
{
    int res = 0;
    while (x)
    {
        res++;
        x /= 10;
    }
    return res;
}
void dfs(int pos, long long x, int cnt)
{

    if (ans != -1 && cnt >= ans)    return;
    if (x == 0 || pos == 0)
    {
        if (ans != -1)  ans = min(ans, cnt);
        else    ans = cnt;
        return;
    }
    if (x < 0)  x = -x;
    // printf("pos = %d, x = %lld, cnt = %d， pow10[pos] = %lld\n", pos, x, cnt, pow10[pos - 1]);
    long long t_x = x;
    int t_cnt = 0;
    while (t_x >= pow10[pos - 1])
    {
        t_x -= num11[pos];
        t_cnt += pos;
    }
    dfs(pos - 1, t_x, cnt + t_cnt);
    t_x = num11[pos + 1] - x;    t_cnt = 0;
    while (t_x >= pow10[pos - 1])
    {
        t_x -= num11[pos];
        t_cnt += pos;
    }
    dfs(pos - 1, t_x, cnt + pos + 1 + t_cnt);
}


void Solve()
{

    long long x;    scanf("%lld", &x);
    // while (cin >> x)    cout << get_len(x);
    ans = -1;
    dfs(get_len(x), x, 0);
    cout << ans << '\n';
}
int main()
{
    pre();
    // while (1)
    Solve();
    getchar(); getchar();
    return 0;
}
